// Regenerates migrations/0002_services.sql from src/shared/services.js.
import { writeFileSync } from 'node:fs';
import { SERVICES } from '../src/shared/services.js';
const q = (s) => "'" + String(s).replaceAll("'", "''") + "'";
const rows = SERVICES.map((s, i) => `  (${q(s.id)}, ${q(s.name)}, ${q(s.category)}, ${q(s.description)}, ${i + 1})`);
writeFileSync(new URL('../migrations/0002_services.sql', import.meta.url),
  '-- Generated by scripts/gen-services-sql.mjs. Prices are left blank on purpose.\n' +
  'INSERT INTO services (id, name, category, description, position) VALUES\n' + rows.join(',\n') + ';\n');
